(31, 3, 17, 'CBD Oil 1000 มก. | เพื่อความผ่อนคลาย', 'จากSEYA', 1900, 2000, '<p style=\"box-sizing: border-box; margin-bottom: 25px; padding: 0px; border: 0px; font-family: Mali; font-size: 20px; vertical-align: baseline; color: rgb(68, 16, 7); line-height: 1.8em; background-color: rgb(254, 247, 240);\"><span style=\"box-sizing: border-box; font-weight: 700; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">Seya | CBD Oil 1000 มก. | เพื่อความผ่อนคลาย</span></p><p style=\"box-sizing: border-box; margin-bottom: 25px; padding: 0px; border: 0px; font-family: Mali; font-size: 20px; vertical-align: baseline; color: rgb(68, 16, 7); line-height: 1.8em; background-color: rgb(254, 247, 240);\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ออกแบบด้วยส่วนผสมของ CBD, MCT Oil และ Terpenes เพื่อส่งเสริมการผ่อนคลาย โดยลดความตึงเครียด ความวิตกกังวล และให้คุณลืมปัญหาของคุณไปได้เลย</span></p><ul style=\"box-sizing: border-box; margin-bottom: 0px; margin-left: 0px; border: 0px; font-family: Mali; font-size: 16px; vertical-align: baseline; list-style: none; color: rgb(68, 16, 7); background-color: rgb(254, 247, 240);\"><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">CBD เข้มข้น 1,000 มก.</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ไม่ออกฤทธิ์ทางจิตและไม่เสพติด</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">แยกโดยมีเพียง cannabidiol และร่องรอยของ terpenes (Myrcene และ Pinene) และ flavonoids เพียงเล็กน้อย</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ใช้น้ำมันตัวพา C8 MCT บริสุทธิ์ที่ผลิตในเยอรมนี</span></li></ul><p style=\"box-sizing: border-box; margin-bottom: 25px; padding: 0px; border: 0px; font-family: Mali; font-size: 20px; vertical-align: baseline; color: rgb(68, 16, 7); line-height: 1.8em; background-color: rgb(254, 247, 240);\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">CBD, MCT Oil และ Terpenes ถูกผสมเข้าด้วยกันเพื่อส่งเสริมการผ่อนคลาย ทำให้เป็นตัวเลือกที่ดีสำหรับการพักผ่อนหลังจากวันที่ยาวนาน ขอแนะนำให้ใช้เป็นประจำเพื่อลดความเครียดและความวิตกกังวลในขณะที่ส่งเสริมสุขภาพโดยทั่วไป</span></p>', 'images11.jpg', 'images11.jpg', 'images11.jpg', 0, 'In Stock', '2025-03-04 19:11:58', NULL),
(32, 3, 17, 'น้ำมัน CBD 150 มก. | สำหรับสัตว์เลี้ยง (พันธุ์เล็ก) | รสแซลมอน', 'จากPetdee', 599, 699, '<p style=\"box-sizing: border-box; margin-bottom: 25px; padding: 0px; border: 0px; font-family: Mali; font-size: 20px; vertical-align: baseline; color: rgb(68, 16, 7); line-height: 1.8em; background-color: rgb(254, 247, 240);\"><span style=\"box-sizing: border-box; font-weight: 700; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">น้ำมัน CBD 150 มก. | สัตว์เลี้ยงพันธุ์เล็ก | รสแซลมอน | สำหรับแมวและสุนัขน้ำหนักไม่เกิน 10 กก.</span></p><p style=\"box-sizing: border-box; margin-bottom: 25px; padding: 0px; border: 0px; font-family: Mali; font-size: 20px; vertical-align: baseline; color: rgb(68, 16, 7); line-height: 1.8em; background-color: rgb(254, 247, 240);\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">น้ำมัน CBD ของ PetDee มาในขวดหยดขนาดพกพาที่มอบโซลูชันเพื่อสุขภาพที่ดีแบบออร์แกนิคสำหรับเพื่อนขนปุยที่คุณรัก ช่วยเพิ่มความเป็นอยู่ที่ดี ส่งเสริมสุขภาพผิว ขนเงางาม ข้อต่อที่แข็งแรง และไลฟ์สไตล์ที่กระฉับกระเฉง</span></p><ul style=\"box-sizing: border-box; margin-bottom: 0px; margin-left: 0px; border: 0px; font-family: Mali; font-size: 16px; vertical-align: baseline; list-style: none; color: rgb(68, 16, 7); background-color: rgb(254, 247, 240);\"><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ยกระดับอารมณ์เพื่อป้องกันความวิตกกังวล</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">เพื่อการพักผ่อน</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ช่วยลดความอักเสบและปวดข้อ</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">สุขภาพขนและผิวที่ดี</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">กระตุ้นความอยากอาหาร</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">รองรับการย่อยอาหาร</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ดีต่อระบบหัวใจ</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">สำหรับสัตว์เลี้ยงน้ำหนักต่ำกว่า 10 กก.</span></li></ul><p style=\"box-sizing: border-box; margin-bottom: 25px; padding: 0px; border: 0px; font-family: Mali; font-size: 20px; vertical-align: baseline; color: rgb(68, 16, 7); line-height: 1.8em; background-color: rgb(254, 247, 240);\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ส่วนผสม: น้ำมันปลาแซลมอนนอร์เวย์พรีเมียม และ CBD Isolate</span></p>', 'images12.jpg', 'images12.jpg', 'images12.jpg', 0, 'In Stock', '2025-03-04 19:12:44', NULL);
