(44, 3, 21, 'คราฟต์โซดา CBD | รสส้มยูซุ | ไม่มีน้ำตาล', 'จากLocal Boys', 99, 0, '<p style=\"box-sizing: border-box; margin-bottom: 25px; padding: 0px; border: 0px; font-family: Mali; font-size: 20px; vertical-align: baseline; color: rgb(68, 16, 7); line-height: 1.8em; background-color: rgb(254, 247, 240);\"><span style=\"box-sizing: border-box; font-weight: 700; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">Local Boys | คราฟต์โซดา BREE CBD | รสส้มยูซุ | ไม่มีน้ำตาล | ได้รับการรับรองอย.</span></p><p style=\"box-sizing: border-box; margin-bottom: 25px; padding: 0px; border: 0px; font-family: Mali; font-size: 20px; vertical-align: baseline; color: rgb(68, 16, 7); line-height: 1.8em; background-color: rgb(254, 247, 240);\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ลิ้มรสความสดชื่นจากคราฟต์โซดา CBD BREE รสส้มยูซุ ให้ความสดชื่นจากน้ำส้ม ยูซุ และมะนาวธรรมชาติ อุดมด้วยวิตามินซีที่ช่วยเพิ่มภูมิคุ้มกันและวิตามินบี 2 ช่วยให้มีพลัง</span></p><p style=\"box-sizing: border-box; margin-bottom: 25px; padding: 0px; border: 0px; font-family: Mali; font-size: 20px; vertical-align: baseline; color: rgb(68, 16, 7); line-height: 1.8em; background-color: rgb(254, 247, 240);\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">เครื่องดื่มแคลอรีต่ำ ไม่เติมน้ำตาล ช่วยให้รู้สึกสดชื่น ผ่อนคลาย และมีสุขภาพดีโดยรวม</span></p><ul style=\"box-sizing: border-box; margin-bottom: 0px; margin-left: 0px; border: 0px; font-family: Mali; font-size: 16px; vertical-align: baseline; list-style: none; color: rgb(68, 16, 7); background-color: rgb(254, 247, 240);\"><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ผสมส้มธรรมชาติและ CBD</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">วิตามินซีและบี 2 เพื่อช่วยเสริมภูมิคุ้มกันและพลังงาน</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ได้รับการรับรองจากอย.</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ผลิตในท้องถิ่น</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">แคลอรีต่ำ</span></li><li style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; border: 0px; font-family: inherit; vertical-align: baseline;\">ไม่เติมน้ำตาล</span></li></ul>', 'images4.jpg', 'images4.jpg', 'images4.jpg', 0, 'In Stock', '2025-03-04 19:27:30', NULL),
